head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil50230";

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil50230.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        form = (document.clmSchdlNotiForm || { elements: [] });
        idInfoArr = [];
        loadTp = 'null';
        isOk = 'null';
        await scwin.checkSave();
        for (let i = 0; i < dlt_idInfoList.getRowCount(); i++) {
            idInfoArr[i] = new idInfo((String(((dlt_idInfoList.getCellData(i, "integ_usr_id") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].integ_usr_id"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "integ_usr_id") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].integ_usr_id"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_idInfoList.getCellData(i, "integ_usr_id") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].integ_usr_id"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "integ_usr_id") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].integ_usr_id"); })())))), (String(((dlt_idInfoList.getCellData(i, "corp_usr_nm") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].corp_usr_nm"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "corp_usr_nm") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].corp_usr_nm"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_idInfoList.getCellData(i, "corp_usr_nm") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].corp_usr_nm"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "corp_usr_nm") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].corp_usr_nm"); })())))), (String(((dlt_idInfoList.getCellData(i, "email") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].email"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "email") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].email"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_idInfoList.getCellData(i, "email") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].email"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "email") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].email"); })())))), (String(((dlt_idInfoList.getCellData(i, "tel_no") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].tel_no"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "tel_no") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].tel_no"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_idInfoList.getCellData(i, "tel_no") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].tel_no"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "tel_no") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].tel_no"); })())))));
        }
        $c.util.getComponent("ipt_userNm").setValue(idInfoArr[0].usr_nm);
        $c.util.getComponent("ipt_telNo").setValue(idInfoArr[0].tel_no);
        $c.util.getComponent("ipt_email").setValue(idInfoArr[0].email);

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil50230.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_doAssgn();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_findCompany_onclick
 * @description btn_findCompany 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_findCompany_onclick = function(e){
    try {
        fn_findCompany(null,1)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil50230.btn_findCompany_onclick' }); }
};

/**
 * @method
 * @name slc_integUsrId_onchange
 * @description slc_integUsrId 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_integUsrId_onchange = function(e){
    try {
        scwin.setIdInfo();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil50230.slc_integUsrId_onchange' }); }
};

/**
 * @method
 * @name btn_doAssgn_onclick
 * @description btn_doAssgn 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_doAssgn_onclick = async function(e){
    try {
        await scwin.doAssgn()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil50230.btn_doAssgn_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_doAssgn
 * @description do Assgn 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_doAssgn = async function () {
    const sbmOptions = {
        id: "tx_doAssgn",
        method: "post",
        action: "/listInvstg/idAssgnPop.do",
        ref: "dma_doAssgnReq",
        target: "dlt_idInfoList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkSave
 * @description check Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSave = async function () {
    if (loadTp === '1') {
        if (isOk !== 'true') {
            await $c.win.alert('오류발생');
        } else {
            await $c.win.alert('저장되었습니다.');
            (function () { const o = $c.win.getOpenerScope(); if (o) { $c.win.setPageFrameSrc($c.win.getFrame(o), null); } else { /* TODO Stage2: [sdd] 부모 창을 못 찾았다 — 새로고침하지 않는다(자기 화면을 다시 열면 무한 고리가 된다) */ } })();
            this.close();
        }
    }
};

/**
 * @method
 * @name setDataVars
 * @description set Data Vars 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.setDataVars = function (ver) {
    setLeadcomVars();
    setDates();
    if (ver === '1') {
        scwin.setDisable();
    } else {
        if (ver === '2' || ver === '3') {
            scwin.setFileDisable();
        }
    }
};

/**
 * @method
 * @name setDisable
 * @description set Disable 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDisable = function () {
    for (let i = 0; i < form.length; i++) {
        form[i].disabled = true;
    }
};

/**
 * @method
 * @name setFileDisable
 * @description set File Disable 처리
 * @returns {void}
 * @hidden N
 */
scwin.setFileDisable = function () {
    const obj1 = form['attachFiles[0]'];
    const obj2 = form['attachFiles[1]'];
    obj1.disabled = true;
    obj2.disabled = true;
};

/**
 * @method
 * @name doAssgn
 * @description do Assgn 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doAssgn = async function () {
    form.action = '/listInvstg/idAssgnPop.do';
    const comName = $c.util.getComponent('ipt_comNm').getValue();
    const usrId = $c.util.getComponent('slc_integUsrId').getValue();
    if (await scwin.checkValue()) {
        if (await $c.win.confirm('[' + comName + '] 회사를 ID [' + usrId + '] 에 배정 하시겠습니까?')) {
            await scwin.tx_doAssgn();
        }
    }
};

/**
 * @method
 * @name checkValue
 * @description check Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValue = async function () {
    if (($c.util.getComponent('ipt_isurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_isurCd').getValue())) === '') {
        await $c.win.alert('법인을 선택하십시오.');
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name doChangeChrg
 * @description do Change Chrg 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doChangeChrg = async function () {
    if (await $c.win.confirm('선택한 담당자가 아닌 로그인한 담당자의 정보를 변경합니다.\r\n담당자정보 변경을 하시겠습니까?')) {
        $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil25100/jldfil25100.xml');
        this.close();
    }
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {*} corpRegNo corpRegNo
 * @param {*} bzRegNo bzRegNo
 * @param {String} comNm comNm
 * @param {String} foundDd foundDd
 * @param {*} secugrp_id secugrp_id
 * @param {*} spot_isu_trd_mkt_tp_cd spot_isu_trd_mkt_tp_cd
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, corpRegNo, bzRegNo, comNm, foundDd, secugrp_id, spot_isu_trd_mkt_tp_cd) {
    $c.util.getComponent("ipt_comNm").setValue(comNm);
    $c.util.getComponent("ipt_isurCd").setValue(isurCd);
};

/**
 * @method
 * @name setIdInfo
 * @description set Id Info 처리
 * @returns {void}
 * @hidden N
 */
scwin.setIdInfo = function () {
    const idx = $c.util.getComponent('slc_integUsrId').getSelectedIndex();
    $c.util.getComponent("ipt_userNm").setValue(idInfoArr[idx].usr_nm);
    $c.util.getComponent("ipt_telNo").setValue(idInfoArr[idx].tel_no);
    $c.util.getComponent("ipt_email").setValue(idInfoArr[idx].email);
};
